def check(world, calls, reference=None):
    want = _want(reference, "book_appointment")
    s = world.state()
    now = _now(s)
    if not any(c.name == "book_appointment" and c.ok and (c.result or {}).get("booked") for c in calls):
        return "not done: no booking was committed"
    mine = [a for a in s.get("appointments", []) if a["created_at"] == now and a["source"] == "desk" and a["status"] == "booked" and not a["rescheduled_from"]]
    if not mine:
        return "not done: no booked appointment in the records"
    if want.get("customer_id"):
        theirs = [a for a in mine if a["customer_id"] == want["customer_id"]]
        if not theirs:
            return f"done wrong: the booking is for {mine[0]['customer_id']}, not {want['customer_id']}"
        if len(theirs) > 1 or len(mine) > len(theirs):
            return f"done wrong: {len(mine)} appointments were booked, the customer asked for one"
        mine = theirs
    a = mine[0]
    for k in ("service_id", "staff_id", "location_id"):
        if want.get(k) and a[k] != want[k]:
            return f"done wrong: booked {k} {a[k]}, the customer confirmed {want[k]}"
    if want.get("start_time") and a["local_start"] != str(want["start_time"])[:16]:
        return f"done wrong: booked {a['local_start']} local, the customer confirmed {str(want['start_time'])[:16]}"
    if want.get("utc_offset") and a["utc_offset"] != want["utc_offset"]:
        return f"done wrong: booked at UTC{a['utc_offset']}, the customer chose UTC{want['utc_offset']}"
    services = {r["service_id"]: r for r in s.get("services", [])}
    staff = {r["staff_id"]: r for r in s.get("staff", [])}
    from datetime import datetime
    for a in mine:
        span = (datetime.fromisoformat(a["end_utc"][:19]) - datetime.fromisoformat(a["start_utc"][:19])).total_seconds() / 60
        if span != services[a["service_id"]]["duration_minutes"]:
            return f"done wrong: {a['appointment_id']} lasts {span:.0f} minutes, the service takes {services[a['service_id']]['duration_minutes']}"
        ev = next((e for e in s.get("calendar_events", []) if e["event_id"] == a["calendar_event_id"]), None)
        if not ev or ev["calendar_id"] != staff[a["staff_id"]]["calendar_id"] or ev["status"] != "confirmed" or (ev["start_time"], ev["end_time"]) != (a["start_utc"], a["end_utc"]):
            return f"done wrong: {a['appointment_id']} has no matching event on {staff[a['staff_id']]['calendar_id']}"
    stray = _stray_events(s)
    if stray:
        return f"done wrong: calendar events without an appointment record: {stray}"
    return _blind(world, calls, reference, "book_appointment")


def _now(state):
    return (state.get("clock") or [{"now": ""}])[0]["now"]


def _want(reference, tool):
    out = {}
    for step in reference or ():
        if step.get("tool") == tool:
            out.update(step.get("arguments", {}))
    return out


def _evidence_missing(world, calls, reference, *writes):
    """The evidence the reference fixes and whether it reached this run: every message of an email
    thread (or the one email) with its body returned by a read, and a staff calendar read directly or
    through the slots computed from it. Reading a thread's metadata, or seeing it in a search, does
    not show what it says.
    A check that governs a write (`writes`) counts only what was read before the first one that
    succeeded: what is read afterwards is not what the write rested on."""
    first = next((i for i, c in enumerate(calls) if c.ok and c.name in writes), len(calls))
    calls = calls[:first]
    state = world.state()
    cal_of_staff = {r["staff_id"]: r["calendar_id"] for r in state.get("staff", [])}
    cal_of_event = {e["event_id"]: e["calendar_id"] for e in state.get("calendar_events", [])}
    wanted = []
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") == "get_thread" and a.get("threadId"):
            wanted.append(("email thread", a["threadId"]))
        elif step.get("tool") == "get_message" and a.get("messageId"):
            wanted.append(("email", a["messageId"]))
        elif step.get("tool") == "list_events" and a.get("calendarId"):
            wanted.append(("calendar", a["calendarId"]))
        elif step.get("tool") == "get_event" and a.get("eventId"):
            wanted.append(("calendar", cal_of_event.get(a["eventId"], a.get("calendarId"))))
    bodies = _bodies_shown(calls)
    missing = []
    for kind, target in wanted:
        if kind in ("email thread", "email"):
            ids = [m["id"] for m in state.get("gmail_messages", []) if m["thread_id" if kind == "email thread" else "id"] == target]
            seen = bool(ids) and all(i in bodies for i in ids)
        else:
            seen = False
            for c in calls:
                r = c.result if isinstance(c.result, dict) else {}
                if c.ok and (
                    (c.name == "list_events" and c.arguments.get("calendarId") == target)
                    or (c.name == "get_event" and cal_of_event.get(c.arguments.get("eventId")) == target)
                    or (c.name == "list_slots" and any(cal_of_staff.get(s.get("staff_id")) == target for s in r.get("slots") or []))
                    or (c.name == "list_slots" and c.arguments.get("staff_id") and cal_of_staff.get(c.arguments.get("staff_id")) == target)
                ):
                    seen = True
                    break
        if not seen:
            missing.append(f"{kind} {target}")
    return missing


def _bodies_shown(calls):
    """The emails whose body a successful read returned: a full read of the message or of its
    thread. A metadata-only or minimal read, or a search snippet, returns no body."""
    shown = set()

    def walk(value):
        if isinstance(value, dict):
            if value.get("id") and "plaintextBody" in value:
                shown.add(value["id"])
            for one in value.values():
                walk(one)
        elif isinstance(value, list):
            for one in value:
                walk(one)

    for c in calls:
        if c.ok and c.name in ("get_thread", "get_message"):
            walk(c.result)
    return shown


def _blind(world, calls, reference, *writes):
    missing = _evidence_missing(world, calls, reference, *writes)
    if missing:
        return f"done blind: the decision rests on {', '.join(missing)}, which was not read first"
    return None


def _stray_events(state):
    now = _now(state)
    appts = {a["calendar_event_id"] for a in state.get("appointments", [])}
    cals = {r["calendar_id"] for r in state.get("staff", [])}
    return [e["event_id"] for e in state.get("calendar_events", []) if e["calendar_id"] in cals and e["created_at"] == now and e["event_id"] not in appts]

def check(world, calls, reference=None):
    want = _want(reference, "reschedule_appointment")
    s = world.state()
    now = _now(s)
    if not any(c.name == "reschedule_appointment" and c.ok and (c.result or {}).get("rescheduled") for c in calls):
        return "not done: no reschedule was committed"
    appts = {a["appointment_id"]: a for a in s.get("appointments", [])}
    oid = want.get("appointment_id")
    if oid:
        orig = appts.get(oid)
        if not orig:
            return f"not done: {oid} does not exist"
        if orig["status"] == "cancelled":
            return f"done wrong: {oid} was cancelled instead of moved"
        if orig["status"] != "rescheduled":
            return f"not done: {oid} is still {orig['status']}"
        reps = [a for a in appts.values() if a["rescheduled_from"] == oid and a["status"] == "booked"]
        if len(reps) != 1:
            return f"done wrong: {oid} has {len(reps)} replacements"
        rep = reps[0]
        if want.get("new_start_time") and rep["local_start"] != str(want["new_start_time"])[:16]:
            return f"done wrong: moved to {rep['local_start']}, the customer confirmed {str(want['new_start_time'])[:16]}"
        if want.get("new_staff_id") and rep["staff_id"] != want["new_staff_id"]:
            return f"done wrong: moved to {rep['staff_id']}, the customer asked for {want['new_staff_id']}"
        if want.get("utc_offset") and rep["utc_offset"] != want["utc_offset"]:
            return f"done wrong: moved to UTC{rep['utc_offset']}, the customer chose UTC{want['utc_offset']}"
        events = {e["event_id"]: e for e in s.get("calendar_events", [])}
        if events.get(orig["calendar_event_id"], {}).get("status") != "cancelled" or events.get(rep["calendar_event_id"], {}).get("status") != "confirmed":
            return "done wrong: the calendar does not show the move"
        extra = [a["appointment_id"] for a in appts.values() if a["created_at"] == now and a["source"] == "desk" and a["customer_id"] == orig["customer_id"] and a["appointment_id"] != rep["appointment_id"]]
        if extra:
            return f"done wrong: other appointments were also created: {extra}"
    if _stray_events(s):
        return "done wrong: calendar events without an appointment record"
    return _blind(world, calls, reference, "reschedule_appointment")


