def check(world, calls, reference=None):
    target = _want(reference, "get_cancellation_policy").get("appointment_id")
    if not target:
        return "broken: the reference fixes no appointment whose cancellation terms were asked about"
    # The fee came back from the records: the appointment's cancellation policy with a fee that
    # applies, or a cancellation of it refused because the fee was not accepted.
    quoted = any(
        c.ok and c.name == "get_cancellation_policy" and (c.result or {}).get("appointment_id") == target and (c.result or {}).get("fee_applies_cents")
        for c in calls
    ) or any(
        c.refused and c.name == "cancel_appointment" and c.arguments.get("appointment_id") == target and "fee" in str(c.error)
        for c in calls
    )
    if not quoted:
        return f"not done: the late fee for cancelling {target} never reached the agent"
    s = world.state()
    a = next((a for a in s.get("appointments", []) if a["appointment_id"] == target), None)
    if not a or a["status"] != "booked":
        return f"done wrong: {target} is {a['status'] if a else 'missing'}; the customer declined the fee and kept it"
    ev = next((e for e in s.get("calendar_events", []) if e["event_id"] == a["calendar_event_id"]), {})
    if ev.get("status") != "confirmed":
        return f"done wrong: the calendar event of {target} is {ev.get('status')}"
    return None


