def check(world, calls, reference=None):
    hid = _want(reference, "release_hold").get("hold_id")
    if not hid:
        return "broken: the reference fixes no hold"
    s = world.state()
    now = _now(s)
    if not any(h["hold_id"] == hid for h in s.get("holds", [])):
        return f"broken: hold {hid} does not exist"
    # There is no tool that reads a hold: the release is how its expiry comes back.
    if not any(c.refused and c.name == "release_hold" and c.arguments.get("hold_id") == hid and "expired" in str(c.error) for c in calls):
        return f"not done: that {hid} had already expired never reached the agent"
    if any(h["created_at"] == now for h in s.get("holds", [])):
        return "done wrong: a new hold was placed; the customer only asked to let the old one go"
    if any(a["created_at"] == now and a["source"] == "desk" for a in s.get("appointments", [])):
        return "done wrong: something was booked; the customer only asked to let the hold go"
    return None


