def check(world, calls, reference=None):
    want = _want(reference, "list_slots")
    loc, date = want.get("location_id"), str(want.get("date") or "")[:10]
    if not loc or not date:
        return "broken: the reference fixes no studio and day"
    # Which occurrence is free came back from the records: the day's slots list each free
    # occurrence with its own offset, and a refused booking names both instants.
    seen = any(
        c.ok and c.name == "list_slots" and (c.result or {}).get("location_id") == loc and (c.result or {}).get("date") == date
        for c in calls
    ) or any(
        c.refused and c.name in ("book_appointment", "hold_slot") and c.arguments.get("location_id") == loc and "happens twice" in str(c.error)
        for c in calls
    )
    if not seen:
        return f"not done: which occurrences of the repeated hour are free at {loc} on {date} never reached the agent"
    s = world.state()
    now = _now(s)
    # Once the occurrence is settled, the time the customer then confirmed is what gets booked.
    book = _want(reference, "book_appointment")
    if book.get("customer_id") and not any(
        a["created_at"] == now and a["source"] == "desk" and a["status"] == "booked" and a["customer_id"] == book["customer_id"]
        for a in s.get("appointments", [])
    ):
        return "not done: nothing was booked once the occurrence was settled"
    # New York's clocks go back at 06:00 UTC on 1 November: 01:00-01:59 local is 05:00-06:59 UTC.
    for a in s.get("appointments", []):
        if a["created_at"] == now and a["source"] == "desk" and "2026-11-01T05:00:00Z" <= a["start_utc"] < "2026-11-01T07:00:00Z":
            return f"done wrong: {a['appointment_id']} was committed at {a['local_start']} UTC{a['utc_offset']}, in the repeated hour the customer could not use"
    for h in s.get("holds", []):
        if h["created_at"] == now and "2026-11-01T05:00:00Z" <= h["start_utc"] < "2026-11-01T07:00:00Z":
            return f"done wrong: hold {h['hold_id']} was placed in the repeated hour"
    return None


